// Fictional design QA: actual workspace wrapper, React tools, Worker auth and in-memory D1. No external requests.
import {build} from 'esbuild';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';
import {createServer} from 'node:http';
import {fileURLToPath} from 'node:url';
import {migrationSchema} from '../../scripts/recovery-status.mjs';
const root=fileURLToPath(new URL('../../',import.meta.url)),origin='http://127.0.0.1:5217';
const worker=await build({entryPoints:[root+'worker/index.js'],bundle:true,write:false,format:'esm',platform:'browser',conditions:['workerd','worker','browser'],external:['cloudflare:*','node:*'],target:'es2022'});
const mf=new Miniflare(convertV4MiniflareOptions({modules:true,script:worker.outputFiles[0].text,compatibilityDate:'2026-10-04',compatibilityFlags:['nodejs_compat'],cf:false,d1Databases:{DB:'fictional-studio-identity'},bindings:{AUTH_SECRET:crypto.randomUUID()+crypto.randomUUID(),APP_ORIGIN:origin},outboundService:()=>{throw Error('No external request permitted in this fixture');}}));
const db=await mf.getD1Database('DB');for(const type of ['table','index','view','trigger']){const rows=migrationSchema().objects.filter(x=>x.type===type).map(x=>db.prepare(x.sql));if(rows.length)await db.batch(rows);}
const headers={Origin:origin,'Content-Type':'application/json','X-SI-Metrics':'exclude','CF-Connecting-IP':'198.51.100.143'};
const signup=await mf.dispatchFetch(origin+'/api/auth/sign-up/email',{method:'POST',headers,body:JSON.stringify({name:'Fictional job-notes applicant',email:'fictional-job-notes@example.invalid',password:crypto.randomUUID()})});
if(signup.status!==200)throw Error('Fictional account setup failed');const cookies=signup.headers.getSetCookie();
const ui=await build({stdin:{contents:`import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {CareerProvider,useCareer} from './src/career-data';import {CareerWorkspace} from './src/career-workspace';import './src/styles.css';
function Preview(){const c=useCareer(),[view,setView]=useState('studio');return <main style={{maxWidth:1100,margin:'24px auto',padding:16}}><p>FICTIONAL LOCAL QA · no live account, model or application service</p><div className="document-actions"><button onClick={()=>{const id=c.saveJob({id:'manual-'+crypto.randomUUID(),title:'Product engineer',company:'Example Studio',location:'London',description:'FICTIONAL ADVERT. Build accessible web applications using JavaScript, TypeScript and React. Explain design decisions and test your work. Visa sponsorship may be available for suitable candidates. Apply through the employer instructions.',apply_url:'https://example.test/jobs/product-engineer',provider:'manual',sponsorship:'not_stated',evidence:'',last_seen:'',first_seen:'2026-11-03T20:00:00.000Z',level:'not_stated'});if(id){c.updateApplication(id,{cv:'FICTIONAL EXISTING DRAFT — keep this exact text.',coverLetter:'FICTIONAL EXISTING LETTER — keep this exact text.',notes:'FICTIONAL PERSONAL NOTE — never replace.',stage:'Preparing'});c.setData(d=>({...d,profile:{...d.profile,cv:'FICTIONAL MASTER PROFILE. I built a personal practice project using JavaScript, TypeScript and React. I tested keyboard navigation and wrote notes about accessible form controls. This is fictional practice experience, not an employment claim.'}}));}}}>Load fictional application</button></div><CareerWorkspace mode={view} go={setView} onReport={()=>{}}/></main>}createRoot(document.getElementById('root')).render(<CareerProvider><Preview/></CareerProvider>);`,resolveDir:root,loader:'tsx'},bundle:true,write:false,format:'esm',platform:'browser',outfile:'fixture.js',define:{'process.env.NODE_ENV':'"production"'}});
const assets=new Map(ui.outputFiles.map(f=>[f.path.split('/').pop(),f.contents]));let apiWrites=0,preparationRequests=0;
const server=createServer(async(req,res)=>{try{
 const url=new URL(req.url,origin);
 if(url.pathname==='/fixture/receipt'){res.setHeader('Content-Type','application/json');return res.end(JSON.stringify({scope:'fictional_local_only',apiWrites,preparationRequests,workspaces:(await db.prepare('SELECT data,revision FROM career_workspaces').all()).results}));}
 if(url.pathname.startsWith('/api/')){if(req.method!=='GET')apiWrites++;if(url.pathname.includes('generate')||url.pathname.includes('prepare'))preparationRequests++;const chunks=[];for await(const c of req)chunks.push(c);const body=Buffer.concat(chunks),response=await mf.dispatchFetch(url.href,{method:req.method,headers:{...req.headers,'X-SI-Metrics':'exclude','CF-Connecting-IP':'198.51.100.143'},...(body.length?{body}:{}),redirect:'manual'});res.writeHead(response.status,Object.fromEntries(response.headers));return res.end(Buffer.from(await response.arrayBuffer()));}
 if(url.pathname==='/'){res.writeHead(200,{'Content-Type':'text/html','Set-Cookie':cookies,'Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; object-src 'none'; frame-src 'none'"});return res.end('<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Application Studio — fictional local account</title><link rel="stylesheet" href="/fixture.css"></head><body><div id="root"></div><script type="module" src="/fixture.js"></script></body></html>');}
 if(assets.has(url.pathname.slice(1))){res.writeHead(200,{'Content-Type':url.pathname.endsWith('.css')?'text/css':'application/javascript'});return res.end(assets.get(url.pathname.slice(1)));}res.writeHead(404);res.end('Not a fixture route');
 }catch(e){console.error(e.message);res.writeHead(500);res.end('Local fixture error');}});
server.listen(5217,'127.0.0.1',()=>console.log(origin));
process.on('SIGINT',async()=>{server.close();await mf.dispose();process.exit(0);});
